          // may inherit the parent Book's authority list.
          authors: resolveChapterAuthors(section.authors, inheritableAuthors),
          startPageLabel: section.startPageLabel,
          endPageLabel: section.endPageLabel,
          confidence: section.confidence ?? (authorityNames.length <= 1 ? "high" : "medium"),
          warnings: [...section.metadataWarnings ?? []]
